//! aproxy-desktop 的构建脚本：确认前端已经构建，再交给 tauri-build（ACL、Windows 资源）。

/// 前端的入口页。`generate_context!` 在编译期把 `dist/` 整个嵌进二进制。
const DIST_INDEX: &str = "dist/index.html";

/// 页面经 IPC 调用的本包命令。列在 app manifest 里之后，它们和核心命令一样要经
/// capabilities/main.json 逐条授权（`allow-<命令名，下划线换成连字符>`）；不列的话，自定义
/// 命令对所有本地页面默认放行。tauri-build 据此在 `permissions/autogenerated/` 写出
/// 权限定义（内容不变就不重写），这些文件随仓库提交、随 crate 发布。
const COMMANDS: &[&str] = &["desktop_info", "titlebar_insets", "set_caption_color"];

fn main() {
    // dist 是 ui/ 用 Vite 构建出来的，被 .gitignore 忽略，新克隆的仓库里没有。缺了它
    // generate_context! 只会报一句「frontendDist ... doesn't exist」，这里先给出能照着做的
    // 说明。不拿占位页面凑数：凑出来的二进制看起来正常，界面却是空的，发布时也认不出来。
    // crates.io 上的包带着构建好的 dist，用户 `cargo install` 不需要 Node.js。
    println!("cargo::rerun-if-changed={DIST_INDEX}");
    if !std::path::Path::new(DIST_INDEX).is_file() {
        println!(
            "cargo::error=aproxy-desktop: 桌面界面的前端还没有构建（缺少 aproxy-desktop/{DIST_INDEX}）。\
             先构建前端（需要 Node.js 20.19+ 或 22.12+）：cd aproxy-desktop/ui && npm ci && npm run build。\
             不需要桌面界面时，用 --no-default-features 构建无界面的 headless 版本。"
        );
        return;
    }

    tauri_build::try_build(
        tauri_build::Attributes::new()
            .app_manifest(tauri_build::AppManifest::new().commands(COMMANDS)),
    )
    .expect("tauri-build 失败");
}
